```openscad
// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle cylinder diameter
knuckle_n   = 5;     // number of equal segments along length
knuckle_y   = 12.5;  // height of knuckle axis above bed (z = plate_thk)
knuckle_r   = knuckle_d / 2;
knuckle_h   = 5;     // knuckle height above axis (overlaps plate for a solid union)

// ---- Pin hole ----
pin_d       = 2;     // pin hole diameter
pin_r       = pin_d / 2;

// ---- Modelling helpers ----
eps         = 0.5;   // cutter overshoot past faces
pitch       = plate_len / knuckle_n;  // 12 mm segment length

union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on the +Y edge: 1st, 3rd, 5th segments (indices 0,2,4)
    for (i = [0 : knuckle_n - 1]) {
        x_c = -plate_len/2 + i * pitch + pitch/2;
        if (i % 2 == 0)
            translate([x_c, plate_wid/2, knuckle_y])
                cylinder(r = knuckle_r, h = knuckle_h);
    }

    // Pin hole along the knuckle axis (x, y = 12.5, z = 3), through all knuckles
    translate([-plate_len/2 - eps, knuckle_y, 0])
        rotate([0, 90, 0])
            cylinder(r = pin_r, h = plate_len + 2*eps);
}
