// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle cylinder diameter
knuckle_n   = 5;     // number of equal segments along length
knuckle_z   = 3;     // knuckle axis height above bed (z)
knuckle_r   = knuckle_d / 2;
knuckle_y   = plate_wid / 2;  // knuckle axis Y position (on +Y edge)

// ---- Pin hole ----
pin_d       = 2;     // pin hole diameter
pin_h       = 0.5;   // extra cut length past faces

// ---- Model ----
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if ((i + 1) % 2 == 1)
                translate([(i + 1 - 1) * plate_len / knuckle_n, knuckle_y, knuckle_z])
                    cylinder(r = knuckle_r, h = plate_thk + 0.5);
        }
    }

    // Pin hole along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        translate([(i + 1 - 1) * plate_len / knuckle_n, knuckle_y, knuckle_z])
            translate([-pin_h/2, -pin_d/2, -pin_h/2])
                cube([pin_h + plate_len, pin_d, pin_h + plate_thk]);
    }
}
