// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle cylinder diameter
knuckle_z   = 3.5;  // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments along length
knuckle_x0  = 0;    // first segment starts at x = 0
knuckle_r   = knuckle_d / 2;

// ---- Pin hole ----
pin_d       = 2.5;  // pin hole diameter
pin_h       = 1;    // cutter overshoot past knuckle faces

// ---- Model ----
union() {
    // Base plate, centred on origin in X/Y
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles along +Y edge (segments 1 and 3)
    for (i = [0 : knuckle_n - 1]) {
        x_seg = knuckle_x0 + i * plate_len / knuckle_n;
        translate([x_seg - plate_len / knuckle_n, plate_wid / 2, 0])
            difference() {
                cylinder(h = plate_thk + 2 * (knuckle_z - plate_thk), r = knuckle_r);
                // Pin hole through every knuckle
                translate([x_seg - plate_len / knuckle_n - pin_h,
                           plate_wid / 2 - pin_h,
                           knuckle_z - pin_h])
                    cube([plate_len / knuckle_n + 2 * pin_h,
                          2 * pin_h + pin_d,
                          pin_h + 1]);
            }
    }
}
