```openscad
// Star-shaped indexing wheel
// 6-pointed star, flat plate lying on the bed, centred on the origin

// ---------------- Parameters ----------------
outer_r   = 30;    // distance of outer points from centre (mm)
inner_r   = 15;    // distance of inner points from centre (mm)
points    = 6;     // number of points (outer = number of inner)
thickness = 3;     // plate thickness (mm)
hole_d    = 6;     // centre through-hole diameter (mm)
eps       = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;          // circle resolution

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    star_outline = concat(
        [ [outer_r, 0] ],
        [ for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points]) [inner_r, 0] ],
        [ for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points]) [outer_r, 0] ]
    );

    // Flat plate
    linear_extrude(height = thickness)
        polygon(points = len(star_outline), hull() = star_outline);

    // Centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
```

