difference() {
    // Star outline (2D), extruded as a flat plate
    linear_extrude(height = thickness) {
        polygon(points = star_points(6, outer_r, inner_r));
    }

    // Central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}

// ---- Generate star vertices ----
// For an even number of points, outer and inner points alternate every 90 degrees,
// so the pattern repeats after 180 degrees.
function star_points(n, outer, inner) =
    concat(
        [for (i = [0 : n / 2 - 1])
            [
                [outer * cos(2 * i * 180 / n), outer * sin(2 * i * 180 / n)],
                [inner * cos(2 * i * 180 / n + 180 / n),
                 inner * sin(2 * i * 180 / n + 180 / n)]
            ]],
        [for (i = [0 : n / 2 - 1])
            [
                [inner * cos(2 * i * 180 / n + 180 / n),
                 inner * sin(2 * i * 180 / n + 180 / n)],
                [outer * cos(2 * i * 180 / n + 180 / n),
                 outer * sin(2 * i * 180 / n + 180 / n)]
            ]]
    );
