```openscad
// Star-shaped indexing wheel
// 8-pointed star, flat plate lying on the bed, centred on the origin

// ---------------- Parameters ----------------
outer_r   = 30;    // distance of outer points from the centre (mm)
inner_r   = 15;    // distance of inner points from the centre (mm)
thickness = 5;     // plate thickness (mm)
hole_d    = 6;     // diameter of the central through-hole (mm)
eps       = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;          // resolution for curved shapes

// ---------------- Outline ----------------
// The star is built as a closed polygon whose vertices alternate between
// outer points and inner points. The outer points sit on the +X axis,
// so the pattern is rotated by 0 degrees (the inner points are then at
// 22.5 degrees, 67.5 degrees, etc.).
module star_outline() {
    polygon(points = combine([
        // Outer points: 0 .. 7, every 45 degrees
        concat([ [outer_r, 0],
                 [outer_r * cos(45), outer_r * sin(45)],
                 [outer_r * cos(90), outer_r * sin(90)],
                 [outer_r * cos(135), outer_r * sin(135)],
                 [outer_r * cos(180), outer_r * sin(180)],
                 [outer_r * cos(225), outer_r * sin(225)],
                 [outer_r * cos(270), outer_r * sin(270)],
                 [outer_r * cos(315), outer_r * sin(315)] ]),

        // Inner points: 0 .. 7, every 45 degrees
        concat([ [inner_r * cos(0), inner_r * sin(0)],
                 [inner_r * cos(45), inner_r * sin(45)],
                 [inner_r * cos(90), inner_r * sin(90)],
                 [inner_r * cos(135), inner_r * sin(135)],
                 [inner_r * cos(180), inner_r * sin(180)],
                 [inner_r * cos(225), inner_r * sin(225)],
                 [inner_r * cos(270), inner_r * sin(270)],
                 [inner_r * cos(315), inner_r * sin(315)] ])
    ]));
}

// ---------------- Part ----------------
difference() {
    // Star plate, built in the print orientation (rests on z = 0)
    linear_extrude(height = thickness)
        star_outline();

    // Central through-hole, extending past the top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
