// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 50;    // plate length along X (mm)
plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 3;     // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_z   = plate_thk + 0.5;  // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of segments along X
knuckle_pitch = plate_len / knuckle_n;  // segment length (mm)
knuckle_ids = [1, 3, 5];              // segment numbers with knuckles

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
function knuckle_x(seg) {
    // segments are 1..knuckle_n, centred on origin in X
    return (seg - 1 - knuckle_n / 2) * knuckle_pitch;
}

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (s = knuckle_ids)
            translate([knuckle_x(s), plate_wid / 2, 0])
                cylinder(d = knuckle_d, h = plate_thk + 0.5);
    }

    // Pin hole along X through every knuckle
    for (s = knuckle_ids)
        translate([knuckle_x(s), plate_wid / 2, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = plate_len + 2 * eps, center = true);
}
