knuckle_odd = [1,3,5]; // segment numbers that get a knuckle

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
knuckle_r = knuckle_d/2;
// X position of segment i (segment 1 starts at x = -plate_len/2)
function seg_x(i) = (i-1)*plate_len/knuckle_n - plate_len/2;

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (s = knuckle_odd)
            translate([seg_x(s), plate_wid/2, 0])
                cylinder(r = knuckle_r, h = plate_thk + eps, $fn = $fn);
    }

    // Pin hole along X through every knuckle
    for (s = knuckle_odd)
        translate([seg_x(s), plate_wid/2, 0])
            cylinder(d = pin_d, h = plate_thk + 2*eps, $fn = $fn);
}
