        // Base plate, centred on origin in X/Y
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along +Y edge (segments 1 and 3)
        for (i = [0 : knuckle_n - 1]) {
            x_s = knuckle_x0 + i * plate_len / knuckle_n;
            x_e = x_s + plate_len / knuckle_n;
            if (i == 0 || i == knuckle_n - 1)  // 1st and 3rd segments
                translate([x_s, plate_wid / 2, 0])
                    cylinder(d = knuckle_d, h = plate_thk + eps, $fn = 64);
        }
