    // Pin hole along the knuckle axis (x, y = 15, z = 3)
    translate([knuckle_x0 - pin_h, plate_wid / 2, knuckle_z])
        cylinder(d = pin_d, h = plate_len + 2 * pin_h + eps, $fn = 64);
