knuckle_d   = 6;    // knuckle cylinder diameter
knuckle_z   = 3;    // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments along X
knuckle_pitch = plate_len / knuckle_n;  // 20 mm segment length

// ---- Pin hole ----
