// ---- Cutting overlap ----
eps         = 0.5;  // extension of cutters past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge (segments 1 and 3)
        for (i = [0 : knuckle_n - 1]) {
            x_c = -plate_len/2 + i * knuckle_pitch;
            if (i == 0 || i == knuckle_n - 1)  // 1st and 3rd segments
                translate([x_c, plate_wid/2, 0])
                    cylinder(d = knuckle_d, h = plate_thk + 0.5, $fn = 64);
        }
    }

    // Pin hole along X through every knuckle axis
    translate([-plate_len/2 - eps, plate_wid/2 - eps, 0])
        cube([plate_len + 2*eps, knuckle_d + 2*eps, plate_thk + 0.5]);
}
