```openscad
// Star-shaped indexing wheel
// 6-pointed star, flat plate lying on the bed (z = 0 upward)

// ---------------- Parameters ----------------
outer_r   = 30;    // distance of outer points from centre (mm)
inner_r   = 18;    // distance of inner points from centre (mm)
points    = 6;     // number of vertices (outer = inner = 6)
thickness = 4;     // plate thickness (mm)
hole_d    = 8;     // central through-hole diameter (mm)
eps       = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;          // circle resolution

// ---------------- Model ----------------
difference() {
    // Star outline, extended through thickness along +Z
    hull() {
        for (i = [0 : points - 1]) {
            // outer point on the axis, inner point offset by 180 deg
            translate([0, 0, 0])
                union() {
                    rotate([0, 0, i * 360 / points])
                        translate([outer_r, 0, 0]);
                    rotate([0, 0, (i + 0.5) * 360 / points])
                        translate([inner_r, 0, 0]);
                }
        }
    }
    // Convex hull of the 12 points (6 outer + 6 inner)
    translate([-outer_r, -outer_r, 0])
        cube([2 * outer_r, 2 * outer_r, thickness]);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
