// Tapered riser block for a beaker
// Print orientation: wide base on the bed (z = 0), narrowing upward

// ---------- Dimensions (mm) ----------
base_size    = 100;   // bottom square side length (z = 0)
top_size     = 80;    // top square side length (z = riser_height)
riser_height = 25;    // total height of the frustum
pocket_size  = 72;    // square pocket side length (top face)
pocket_depth = 5;     // square pocket depth from top face

eps = 0.5;            // overcut for clean boolean differences

// ---------- Derived ----------
base_h = riser_height;      // base is at z = 0
top_z  = riser_height;      // top face is at z = 25

// ---------- Model ----------
difference() {
    // Square frustum body
    linear_extrude(height = riser_height)
        polygon(points = [
            [-base_size/2, -base_size/2],
            [ base_size/2, -base_size/2],
            [ base_size/2,  base_size/2],
            [-base_size/2,  base_size/2]
        ]);

    // Tilt the extrusion so the top face is at the correct height:
    // rotate([90,0,0]) maps polygon Y to Z, so rotate by -90 to have
    // the polygon span z = 0 .. riser_height and extrude along +X.
    // The polygon is drawn in (X, Z), extruded along +Y, then shifted
    // so the frustum spans z = 0 .. riser_height.
    translate([0, riser_height, 0])
        rotate([-90, 0, 0])
            linear_extrude(height = base_size)
                polygon(points = [
                    [-top_size/2, -top_size/2],
                    [ top_size/2, -top_size/2],
                    [ top_size/2,  top_size/2],
                    [-top_size/2,  top_size/2]
                ]);

    // Square pocket in the top face, centred
    translate([0, 0, top_z - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
