rim_w       = 4;    // rim width
hub_d       = 20;   // hub diameter
axle_d      = 5;    // axle hole diameter
spoke_w     = 4;    // spoke width
spoke_count = 4;    // number of spokes, evenly spaced
start_angle = 0;    // first spoke along +X axis

// --- Derived ---
