hub_r = hub_d / 2;

difference() {
    union() {
        // Outer rim
        cylinder(d = rim_d, h = part_t);
        // Hub (overlaps rim slightly for a clean union)
        translate([0, 0, -0.01])
            cylinder(d = hub_d, h = part_t + 0.02);
        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, start_angle + i * 360 / spoke_count])
                translate([hub_r - 0.01, -spoke_w / 2, 0])
                    cube([rim_r - hub_r + 0.02, spoke_w, part_t]);
        }
    }
    // Axle hole through centre
    translate([0, 0, -1])
        cylinder(d = axle_d, h = part_t + 2);
}
