// Star-shaped indexing wheel
// 5-pointed star, flat plate lying on the bed, centred on the origin

// ---------------- Parameters ----------------
outer_r   = 30;    // distance of outer points from the centre (mm)
inner_r   = 15;    // distance of inner points from the centre (mm)
points    = 5;     // number of points (and inner points)
thickness = 3;     // plate thickness (mm)
hole_d    = 8;     // central through-hole diameter (mm)
eps       = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = 96;          // resolution for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline, built with a for loop and rotate([z, a, 0])
    hull() {
        for (i = [0 : points - 1]) {
            rotate([90, i * 360 / points, 0])
                translate([0, 0, -eps])
                    linear_extrude(thickness + 2 * eps)
                        polygon([
                            [outer_r, 0],
                            [inner_r, 0],
                            [0, inner_r],
                            [-outer_r, 0],
                            [0, -inner_r]
                        ]);
        }
    }

