```openscad
// Star-shaped indexing wheel
// 8-pointed star, flat plate lying on the bed, centred on the origin

// ---------------- Parameters ----------------
outer_r   = 40;    // distance of outer points from the centre (mm)
inner_r   = 20;    // distance of inner points from the centre (mm)
points    = 8;     // number of points (outer and inner, evenly spaced)
thickness = 5;     // plate thickness (mm)
hole_d    = 6;     // diameter of the central through-hole (mm)
eps       = 0.5;   // overshoot for clean boolean cuts (mm)

$fn = points * 2;  // resolution for curved shapes

// ---------------- Outline ----------------
// Polygon of the star seen from above: outer points on the +X axis,
// followed by the inner points, all evenly spaced in angle.
module star_outline() {
    outline = concat(
        [ [outer_r, 0] ],
        [ for (i = [1 : points - 1])
            rotate([0, 0, i * 360 / points])
                [outer_r * cos(360 / points), outer_r * sin(360 / points)] ],
        [ for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points])
                [inner_r * cos(180 / points), inner_r * sin(180 / points)] ],
        [ [-outer_r, 0] ]
    );
    // close the loop
    outline = outline + [outline[0]];
    polygon(points = len(outline) / 2, hull = outline);
}

// ---------------- Part ----------------
difference() {
    // star body, centred in XY, resting on z = 0
    translate([0, 0, 0])
        linear_extrude(height = thickness)
            star_outline();

    // central through-hole, extending past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
