```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;    // distance of outer points from centre (mm)
inner_r   = 20;    // distance of inner points from centre (mm)
points    = 5;     // number of points (outer = inner + 5*90deg)
plate_t   = 3;     // plate thickness (mm)
hole_d    = 6;     // central through-hole diameter (mm)
eps       = 0.5;   // cutter overshoot past faces (mm)
$fn       = 96;    // circle resolution

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0]);
        }
    }
    // Inner points (concave vertices)
    for (i = [0 : points - 1]) {
        rotate([0, 0, (i + 0.5) * 360 / points])
            translate([inner_r, 0, 0]);
    }
    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Thickness ----------------
linear_extrude(height = plate_t) {
    // Same outline in XY, now 2D
    hull() {
        for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0]);
    }
    for (i = [0 : points - 1])
        rotate([0, 0, (i + 0.5) * 360 / points])
            translate([inner_r, 0]);
}
difference() {
    // (hull of outer points) - (hull of inner points) is a star
    hull() {
        for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0]);
    }
    hull() {
        for (i = [0 : points - 1])
            rotate([0, 0, (i + 0.5) * 360 / points])
                translate([inner_r, 0]);
    }
    // keep the centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
