// Star-shaped indexing wheel
// 6-pointed star, centred on origin, first outer point on +X axis

// ---- Dimensions (mm) ----
outer_r   = 35;    // distance of outer points from centre
inner_r   = 21;    // distance of inner points from centre
thickness = 4;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 0.5;   // overshoot for clean boolean cuts

$fn = 96;          // smoothness of curved shapes

// ---- Model ----
difference() {
    // Star outline, extruded as a flat plate
    linear_extrude(height = thickness) {
        polygon(points = star_points(6, outer_r, inner_r));
    }

    // Central hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}

// ---- Helper: vertices of a 2D star polygon ----
function star_points(n, outer_r, inner_r) =
    [for (i = [0 : n - 1])
        rotate(i * 360 / n) [
            (i % 2 == 0) ? outer_r : inner_r,
            cos((i % 2) * 180) * sin(i * 360 / n)
        ]];
