// Star-shaped indexing wheel
// 8-pointed star, flat plate lying on the bed, centred on the origin

// ---------------- Parameters ----------------
outer_r   = 35;   // distance of outer points from the centre (mm)
inner_r   = 21;   // distance of inner points from the centre (mm)
points    = 8;    // number of points (outer and inner, evenly spaced)
thickness = 3;    // plate thickness (mm)
hole_d    = 6;    // diameter of the central through-hole (mm)
eps       = 0.5;  // small overlap for clean boolean cuts (mm)

$fn = 96;         // resolution for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline, extruded as a plate from z = 0 to z = thickness
    // rotate([90,0,0]) puts the 2D plane along +Z, so the piece sits on the bed
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                // outer points, first on the +X axis
                for (i = [0 : points - 1])
                    [outer_r * cos(2 * pi * i / points),
                     outer_r * sin(2 * pi * i / points)],
                // inner points, staggered in angle
                for (i = [0 : points - 1])
                    [inner_r * cos((2 * i + 1) * pi / points),
                     inner_r * sin((2 * i + 1) * pi / points)]
            ]);

    // Central through-hole, extending past both faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
