// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;   // distance of outer points from centre (mm)
inner_r   = 20;   // distance of inner points from centre (mm)
point_n   = 8;    // number of points (outer and inner)
plate_t   = 3;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // cutter overshoot past faces (mm)

$fn = 96;         // smoothness of curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline, centred on origin, first outer point on +X axis
    star_outline(outer_r, inner_r, point_n);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Helpers ----------------
// 8-pointed star: alternate between outer and inner points every 45 degrees
module star_outline(outer_r, inner_r, point_n) {
    for (i = [0 : point_n - 1]) {
        angle = i * 2 * 3.141592653589793 / point_n;
        // outer point at angle, inner point at angle + 90 degrees
        outer_p = [outer_r * cos(angle), outer_r * sin(angle)];
        inner_p = [inner_r * cos(angle + pi / 2), inner_r * sin(angle + pi / 2)];
        // convex hull of the two points gives the star's outline segment
        hull() {
