// Tapered riser block with a square pocket in the top face
// Print orientation: wide base on the bed (z = 0), narrowing upward

// ---------- Dimensions (mm) ----------
base_size    = 80;   // side length of the bottom square (z = 0)
top_size     = 40;   // side length of the top square (z = riser_h)
riser_h      = 20;   // overall height of the frustum
pocket_size  = 32;   // side length of the square pocket
pocket_depth = 5;    // depth of the pocket measured from the top face

