$fn          = 64;   // curve resolution (no curved features here)

// ---------- Derived ----------
base_half = base_size / 2;
top_half  = top_size / 2;

// Slope factor so that the side faces, extended past the top face,
// meet at 90 degrees (edges parallel to X and Y throughout).
slope_fact = riser_h / (base_half - top_half);

// ---------- Model ----------
difference() {
    union() {
        // Lower straight-walled section: base up to z = riser_h - eps
        translate([-base_half, -base_half, 0])
            cube([base_size, base_size, riser_h - eps]);

        // Upper tapered section: from z = riser_h - eps up to z = riser_h + eps
        // (starts with a square of side base_size - 2*eps and tapers to top_size)
        translate([-base_half + eps, -base_half + eps, riser_h - eps])
            linear_extrude(height = eps + 0.01)
                polygon([
                    [-base_half + eps, -base_half + eps],
                    [ base_half - eps, -base_half + eps],
                    [ base_half - eps,  base_half - eps],
                    [-base_half + eps,  base_half - eps]
                ]);
    }

    // Square pocket cut into the top face, centred
    translate([-pocket_size / 2, -pocket_size / 2, riser_h - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
