outer_r = outer_d / 2;
hub_r   = hub_d / 2;
cut     = 0.5;       // overshoot for clean boolean cuts

$fn = 96;

difference() {
    // Outer disc
    cylinder(h = thickness, r = outer_r);

    // Rim hollow
    translate([0, 0, -cut])
        cylinder(h = thickness + 2 * cut, r = outer_r - rim_w);

    // Hub
    cylinder(h = thickness, r = hub_r);

    // Axle hole
    translate([0, 0, -cut])
        cylinder(h = thickness + 2 * cut, d = axle_d);

    // Spokes from hub to rim, first along +X
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([hub_r, -spoke_w / 2, 0])
                cube([(outer_r - hub_r) + cut, spoke_w, thickness]);
}
