        // Knuckle cylinders on 1st and 3rd segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0)
                translate([knuckle_x0 + i * knuckle_pitch,
                           plate_wid/2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 0.01);
        }
    }

    // Pin hole along X through every knuckle
    for (i = [0 : knuckle_n - 1])
        translate([knuckle_x0 + i * knuckle_pitch - eps,
                   plate_wid/2,
                   knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = plate_len + 2*eps);
}
