```openscad
// Star-shaped indexing wheel
// 8-pointed star, flat plate lying on the bed, centred on the origin

// ---------------- Parameters ----------------
outer_r   = 35;   // distance of outer points from centre (mm)
inner_r   = 21;   // distance of inner points from centre (mm)
points    = 8;    // number of points / number of inner valleys
thickness = 4;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // overshoot for clean boolean cuts (mm)

$fn = 96;         // overall smoothness

// ---------------- Model ----------------
difference() {
    // Star outline, drawn in the XY plane, extruded upward.
    // rotate([90,0,0]) maps the 2D radius onto +Z, so the profile
    // sits between z = 0 and z = thickness.
    translate([0, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = thickness)
                polygon(points = [
                    for (i = [0 : points - 1]) {
                        angle = i * 360 / points;
                        // even i -> outer point, odd i -> inner point
                        r = (i % 2 == 0) ? outer_r : inner_r;
                        [r * cos(angle), r * sin(angle)]
                    }
                ]);

    // Central through-hole, extending past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}
