difference() {
    // Solid square frustum: hull between the bottom and top plates
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, riser_height]);

        translate([-top_size/2, -top_size/2, riser_height])
            cube([top_size, top_size, eps]);
    }

    // Square pocket cut into the top face, centred on the origin
    translate([-pocket_size/2, -pocket_size/2, riser_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
