// ---------- Parameters ----------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 30;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_z   = 3;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of equal segments along X
knuckle_r   = knuckle_d / 2;                    // knuckle radius (mm)
knuckle_off = plate_wid / 2 - knuckle_r;        // Y offset of knuckle centres (mm)

pin_d       = 2.5;   // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
segment_len = plate_len / knuckle_n;   // 8 mm segment length

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge: segments 1, 3, 5 (0‑based indices 0, 2, 4)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0)
                translate([-segment_len * i + segment_len / 2,
                           knuckle_off,
                           knuckle_z])
                    cylinder(r = knuckle_r, h = plate_thk + 0.01);
        }
    }

    // Pin hole running along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        translate([-segment_len * i + segment_len / 2,
                   knuckle_off,
                   knuckle_z])
            cylinder(r = pin_d / 2, h = plate_len + 2 * eps);
    }
}
