knuckle_z   = 4;    // knuckle axis height above bed (z)
knuckle_n   = 5;    // number of equal segments along length
knuckle_r   = knuckle_d / 2;
knuckle_h   = 4;    // knuckle height above its segment (avoids coplanar faces)

