// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_z   = 4;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of equal segments along X
knuckle_odd = [1,3,5]; // segments that carry a knuckle (1-based)

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
segment_len = plate_len / knuckle_n;   // 8 mm segment length
function knuckle_x(s) = (s - 1) * segment_len + segment_len / 2; // segment centre X

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (s = knuckle_odd)
            translate([knuckle_x(s), plate_wid/2, 0])
                cylinder(d = knuckle_d, h = plate_thk + 0.01); // tiny overlap into plate for clean union
    }

    // Pin hole along X through every knuckle
    for (s = knuckle_odd)
        translate([knuckle_x(s), plate_wid/2, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = segment_len + 2*eps, center = true);
}
