```openscad
// Star-shaped indexing wheel
// 5-pointed star, flat plate, printed lying flat on the bed

// ---- Parameters ----
star_points   = 5;    // number of points on the star
outer_radius = 30;   // distance of outer points from centre (mm)
inner_radius = 18;   // distance of inner points from centre (mm)
thickness    = 3;    // plate thickness (mm)
hole_d       = 6;    // centre through-hole diameter (mm)
eps          = 0.5;  // overshoot for clean boolean cuts (mm)

$fn = 96;            // resolution for curved shapes

// ---- Model ----
difference() {
    // Star outline, built with a rotate-extrude so the first outer point
    // lies on the +X axis. The profile is drawn in the XZ plane (2D y -> Z).
    translate([0, 0, -eps])
        linear_extrude(height = thickness, center = true)
            rotate_extrude($fn = 2 * star_points)
                polygon(points = [
                    [outer_radius, 0],
                    for (i = [1 : star_points - 1])
                        [outer_radius * cos(2 * i * 3.14159265 / star_points),
                         outer_radius * sin(2 * i * 3.14159265 / star_points)],
                    [inner_radius, 0],
                    for (i = [1 : star_points - 1])
                        [inner_radius * cos(2 * i * 3.14159265 / star_points),
                         inner_radius * sin(2 * i * 3.14159265 / star_points)]
                ]);

    // Centre through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}
