part_t      = 6;    // wheel thickness
outer_d     = 100;  // outer rim diameter
rim_w       = 6;    // rim width
hub_d       = 14;   // hub diameter
axle_d      = 8;    // axle hole diameter
spoke_w     = 5;    // spoke width
spoke_count = 6;    // number of spokes, first along +X axis

// --- Derived ---
inner_d = outer_d - 2 * rim_w;  // ring inner diameter (rim bore)
spoke_len = (outer_d / 2 - hub_d / 2) / cos(pi / spoke_count);  // radial length from hub to rim

// --- Model ---
difference() {
    union() {
        // Outer rim (ring)
        difference() {
            cylinder(d = outer_d, h = part_t);
            translate([0, 0, -1]) cylinder(d = inner_d, h = part_t + 2);
        }

        // Hub
        cylinder(d = hub_d, h = part_t);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2 - 1, -spoke_w / 2, 0])
                    cube([spoke_len + 1, spoke_w, part_t]);
    }

    // Axle hole through hub centre
    translate([0, 0, -1]) cylinder(d = axle_d, h = part_t + 2);
}
