// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 35;    // distance of outer points from centre
inner_r   = 17.5;  // distance of inner points from centre
points    = 5;     // number of points (and inner points)
plate_t   = 4;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 0.5;   // cutter overshoot past faces

$fn = 96;          // smoothness for curved operations

// ---------------- Model ----------------
difference() {
    // Star outline, centred on origin, first outer point on +X axis
    hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    cube([outer_r, outer_r, plate_t]);
        }
    }

    // Inner notch cuts that turn the hull into a 5-pointed star
    for (i = [0 : points - 1]) {
        rotate([0, 0, i * 360 / points])
            translate([inner_r, 0, -eps])
                cube([outer_r - inner_r, outer_r - inner_r, plate_t + 2 * eps]);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
