// Star-shaped indexing wheel
// 8-pointed star, centred on origin, flat plate lying on the bed

// ---- Dimensions (mm) ----
outer_r   = 35;    // distance of outer points from centre
inner_r   = 21;    // distance of inner points from centre
thickness = 5;     // plate thickness (Z)
hole_d    = 8;     // central through-hole diameter
eps       = 1;     // overshoot for clean boolean cuts

$fn = 96;          // smoothness of curved shapes

difference() {
    // Star outline, drawn in XY, then extruded upward
    rotate([90, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = star_points(outer_r, inner_r, 8));

    // Central hole through the full thickness
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 96);
}

// Generate the 8-pointed star polygon (alternating outer/inner vertices)
function star_points(outer_r, inner_r, points) =
    concat(
        [for (i = [0 : points / 2 - 1])
            [outer_r * cos(2 * pi * i / points),
             outer_r * sin(2 * pi * i / points)]],
        [for (i = [0 : points / 2 - 1])
            [inner_r * cos(2 * pi * (i + 0.5) / points),
             inner_r * sin(2 * pi * (i + 0.5) / points)]]
    );
