    translate([0, 0, 0])
        linear_extrude(height = thickness)
            polygon(points = [
                // Outer points, first on +X, evenly spaced
                concat(
                    [[outer_r, 0]],
                    [for (i = [1 : points - 1])
                        rotate([0, 0, i * 360 / points])
                            [outer_r, 0]]
                ),
                // Inner points, evenly spaced, staggered by 180/points degrees
                rotate([0, 0, 180 / points])
                    concat(
                        [[inner_r, 0]],
                        [for (i = [1 : points - 1])
                            rotate([0, 0, i * 360 / points])
                                [inner_r, 0]]
                    )
            ]);

    // Central through-hole, extending past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
