plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_z   = 3;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of equal segments along X
knuckle_r   = [1, 3, 5]; // segment indices (1-based) with knuckles

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
segment_len = plate_len / knuckle_n;   // 12 mm segment length
knuckle_x   = function(i) {           // X of segment i centre
    return (i - 1) * segment_len + segment_len / 2;
};

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on specified segments
        for (s = knuckle_r)
            translate([knuckle_x(s), plate_wid / 2, 0])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = plate_thk + 0.01, $fn = 96);
    }

    // Pin hole along X through every knuckle
    for (s = knuckle_r)
        translate([knuckle_x(s), plate_wid / 2, knuckle_z])
            rotate([0, 0, 90])
                cylinder(d = pin_d, h = segment_len + 2 * eps, $fn = 64);
}
