            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (indices 0, 2, 4)
        for (i = [0 : knuckle_n - 1]) {
            x = (i - (knuckle_n - 1) / 2) * plate_len / knuckle_n;
            translate([x, plate_wid/2, 0])
                cylinder(r = knuckle_r, h = plate_thk + 0.01);
