    // Spokes
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / spoke_count])
            translate([hub_r - 1, -spoke_w / 2, 0])
                cube([outer_r - hub_r + 2, spoke_w, part_t]);
