```openscad
// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part_t

$fn = 96;

// --- Dimensions (mm) ---
part_t      = 5;     // part thickness (Z)
outer_d     = 100;   // outer rim diameter
rim_w       = 6;     // rim width (radial)
hub_d       = 16;    // hub diameter
axle_d      = 6;     // axle hole diameter
spoke_w     = 4;     // spoke width (tangential)
spoke_count = 5;     // number of spokes
spoke_len   = 0;     // will be set to hub radius + rim width

eps         = 0.5;   // cutter overshoot

// --- Derived ---
outer_r = outer_d / 2;
hub_r   = hub_d / 2;
spoke_len = hub_r + rim_w;

// --- Model ---
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(h = part_t, r = outer_r);
            translate([0, 0, -eps])
                cylinder(h = part_t + 2 * eps, r = outer_r - rim_w);
        }
        // Hub
        cylinder(h = part_t, r = hub_r);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([spoke_len, spoke_w, part_t]);
    }
    // Axle hole
    translate([0, 0, -eps])
        cylinder(h = part_t + 2 * eps, d = axle_d);
